cat > /workspace/tmp/diff_fuzz2.py <<'PYEOF'
import random, sys, json
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import gateway, oracle

DIR = {"sip:ember@studio.test": ["sip:e1@alias.studio.test", "tel:+12025550121", "sip:Em@Alias.Studio.TEST."],
       "sip:desk@sales.test": ["tel:+12025550122", "sip:desk@SALES.TEST"],
       "sip:trunk@trunk.test": ["tel:+15550001111"],
       "sip:x@other.test": []}
ACC = {"s1": {"primary":"sip:ember@studio.test","allow":["sip:desk@sales.test"]},
       "s2": {"primary":"sip:trunk@trunk.test","allow":[]},
       "s3": {"primary":"sip:desk@sales.test","allow":["sip:x@other.test"]}}
GW = {"edge": {"local_domains":["studio.test","sales.test"],"peers":{"p1":["trunk.test"],"p2":["studio.test","sales.test"],"p3":[]}},
      "inside": {"local_domains":[],"peers":{"edge":["studio.test"]}},
      "wide": {"local_domains":["other.test"],"peers":{"edge":["studio.test","sales.test"],"p2":["sales.test"]}}}

SIPS = ["sip:ember@studio.test","SIP:%65mber@STUDIO.TEST.","sip:e1@alias.studio.test","sip:Em@Alias.Studio.TEST.",
        "sip:desk@sales.test","sip:desk@SALES.TEST","sip:trunk@trunk.test","sip:x@other.test",
        "sip:unknown@studio.test","sip:a@b.test","sip:%61@b.test","sip:a-b.c!d~e*f'g(h)+j@sub.domain.example",
        "sip:anonymous@anonymous.invalid","sip:anonymous@ANONYMOUS.INVALID."]
TELS = ["tel:+12025550121","tel:+12025550122","TEL:+15550001111","tel:+15559998888","tel:+1"]
ALLU = SIPS + TELS

def addr(rng, params=True, allow_anon=True):
    pool = [u for u in ALLU if (allow_anon or u.lower() not in ("sip:anonymous@anonymous.invalid",)) ]
    u = rng.choice(pool)
    st = rng.random()
    if st < .3: v = "<%s>" % u
    elif st < .45: v = u
    elif st < .6: v = "%s <%s>" % (rng.choice(["Alice","A B","a.b-c","\"q t\"","\"a;b,<x@y>\"","\"es \\\"c\""]), u)
    elif st < .7: v = "< %s >" % u
    elif st < .8: v = "%s<%s>" % (rng.choice(["Bob","x-y"]), u)
    else: v = "<%s>" % u
    if params and rng.random() < .35:
        v += rng.choice([";tag=q7"," ; tag = %s" % ("T"*rng.randint(1,60)), " ;TAG= abc ","\t;\ttag\t=\tv1"])
    return v

def gen_job(rng, k):
    lines = []
    method = rng.choice(["MESSAGE","INVITE"])
    lines.append("%s %s SIP/2.0" % (method, rng.choice([u for u in SIPS])))
    def add(nm, val): lines.append("%s: %s" % (nm, val))
    add(rng.choice(["From","from","f","F","From"]), addr(rng))
    add(rng.choice(["To","TO","t"]), addr(rng))
    add(rng.choice(["Call-ID","i","CALL-ID"]), rng.choice(["c","cid_1","x"*rng.randint(1,128),"a.b@c-d+e"]))
    add("CSeq", rng.choice(["%d %s"%(rng.randint(1,2147483647), method),
                            "%04d %s"%(rng.randint(0,9999), method), "1  %s"%method, "1\t%s"%method]))
    if rng.random() < .5: add(rng.choice(["Privacy"]), rng.choice(["id","none","ID","NoNe"]))
    if rng.random() < .4:
        n = rng.choice([1,1,1,2,2])
        members = []
        for _ in range(n):
            members.append(addr(rng, params=False, allow_anon=False))
        if rng.random() < .3 and len(members)==2:  # keep one sip one tel most of the time
            members = ["<%s>"%rng.choice(SIPS), "<%s>"%rng.choice(TELS)]
        lines.append("P-Asserted-Identity: " + rng.choice([", ", ",", " ,"]) .join(members))
        if rng.random() < .2: lines.append("p-asserted-identity: " + addr(rng, params=False, allow_anon=False))
    if rng.random() < .3: add("P-Preferred-Identity", addr(rng, params=False, allow_anon=False))
    if rng.random() < .2: add("Remote-Party-ID", addr(rng, params=False, allow_anon=False))
    if rng.random() < .3: add(rng.choice(["Content-Type","c"]), rng.choice(["text/plain","application/x-y","a\tb","x"*200,"A!*$&/"]))
    if rng.random() < .25: add(rng.choice(["Via","Authorization","Contact","X-Foo"]), "<sip:a@b>;tag=z")
    if rng.random() < .2: lines[-1] = lines[-1] + "\r\n\t" + rng.choice(["continued","  more "])
    body = rng.choice(["hello","", "a\r\nb", "z"*rng.randint(1,300), "\t x", "~!@#$%^&*()_+" ])
    lines.append("Content-Length: %s" % rng.choice(["%d"%len(body), "0"*rng.randint(1,4)+"%d"%len(body)]))
    text = "\r\n".join(lines) + "\r\n\r\n" + body
    job = {"gateway": rng.choice(list(GW)),
           "ingress": rng.choice([{"kind":"local","subject":rng.choice(list(ACC))},
                                  {"kind":"peer","name":rng.choice(["p1","p2","p3","edge","nope"])},
                                  {"kind":"untrusted"}]),
           "trusted_out": rng.random() < .5, "raw": text}
    if k > 0 and rng.random() < .25:
        job2 = dict(job); del job2["raw"]; job2["source"] = rng.randrange(k); return job2
    return job

TALLY = {}
diffs = 0
random.seed(31337)
for it in range(4000):
    rng = random.Random(it*7919+11)
    n = rng.randint(1,8)
    jobs = [gen_job(rng, k) for k in range(n)]
    b = {"directory": DIR, "accounts": ACC, "gateways": GW, "jobs": jobs}
    g1 = gateway.process(b); g2 = oracle.process(b)
    for r in g1["results"]:
        key = "accept" if r["status"]=="accept" else r["reason"]
        TALLY[key] = TALLY.get(key,0)+1
    if g1 != g2:
        diffs += 1
        if diffs <= 8:
            for i,(x,y) in enumerate(zip(g1["results"], g2["results"])):
                if x != y:
                    print("=== batch", it, "job", i)
                    print(json.dumps(b["jobs"][i])[:1200])
                    print("gateway:", json.dumps(x)[:400])
                    print("oracle :", json.dumps(y)[:400])
print("diff batches", diffs, TALLY)
PYEOF
cd /workspace/tmp && python3 diff_fuzz2.py 2>&1 | tail -40
